
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lc_wpbe_whs_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lc_wpbe_whs", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.143324881392704e+00, -4.060575436776154e+00, -3.944699822905064e+00, -3.784344915269140e+00, -3.566185272534076e+00, -3.276568173423065e+00, -2.905372116049987e+00, -2.452890764931650e+00, -1.938615119189707e+00, -1.401925747609413e+00, -8.769064226872826e-01, -5.398785893155837e-01, -4.499047452477214e-01, -3.356181655728188e-01, -1.947512135296788e-01, -7.533730511049203e-02, -1.271622610986762e-02, -3.188311167306584e-04, -2.698059407570533e-06, -3.725742806822025e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


